const $ = (s) => document.querySelector(s);
const esc = (str) => String(str).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const getUni = id => universities.find(u => u.id === id) || universities[0];
const getProgram = id => programs.find(p => p.id === id) || programs[0];
const getGuide = () => guides[state.guide];

function showToast(message) { const toast = $('.toast'); toast.textContent = message; toast.classList.add('show'); clearTimeout(window.__toast); window.__toast = setTimeout(() => toast.classList.remove('show'), 2600); }
function navigate(view, extra = {}) { Object.assign(state, { view, ...extra }); window.scrollTo({ top: 0, behavior: 'smooth' }); render(); }
function navButton(label, view, active = false) { return `<button class="${active ? 'active' : ''}" data-view="${view}">${label}</button>`; }
function saveButton(type, id, saved) { return `<button class="save-button ${saved ? 'saved' : ''}" data-save-type="${type}" data-id="${id}">${saved ? 'Saved' : 'Save'}</button>`; }
function sourceNote(source, verified, url, tone = 'green') { return `<div class="source-note ${tone}"><span><strong>${esc(source)}</strong> · Verified ${esc(verified)} · <a href="${url}" target="_blank" rel="noreferrer">View official source ↗</a></span></div>`; }

function shell(content) {
  const guideActive = ['apply','international','life'].includes(state.guide) && state.view === 'guide';
  return `<div class="utility-bar"><span>Independent research workspace</span><span>Source-aware programme data</span><span class="utility-highlight">No subjective rankings</span></div>
    <nav class="main-nav"><button class="brand" data-view="home"><span class="brand-mark"><span>U</span></span><span class="brand-name">University<br>Tracker<small>Research your next chapter</small></span></button><div class="nav-links">${navButton('Discover', 'discover', state.view === 'discover')}${navButton('How to apply', 'guide', guideActive && state.guide === 'apply')}${navButton('International students', 'guide', guideActive && state.guide === 'international')}${navButton('Student life', 'guide', guideActive && state.guide === 'life')}${navButton('Scholarships', 'scholarships', state.view === 'scholarships')}</div><div class="nav-actions"><button class="icon-button" aria-label="Search" data-view="discover">⌕</button><button class="profile-button" data-view="tracker">My tracker <span>(${state.tracker.length})</span></button></div></nav>
    <main>${content}</main>${footer()}<div class="toast"></div>`;
}

function footer() { return `<footer class="footer"><div class="container"><div class="footer-grid"><div><div class="brand"><span class="brand-mark"><span>U</span></span><span class="brand-name">University<br>Tracker<small>Research your next chapter</small></span></div><p style="margin-top:20px;max-width:250px;">A practical research workspace for discovering programmes, understanding requirements and planning an application.</p></div><div><h3>Explore</h3><a href="#" data-view="discover">University directory</a><a href="#" data-view="scholarships">Scholarships</a><a href="#" data-view="compare">Compare programmes</a></div><div><h3>Plan</h3><a href="#" data-guide="apply">How to apply</a><a href="#" data-guide="international">International students</a><a href="#" data-view="tracker">Application tracker</a></div><div><h3>Trust</h3><p>Official sources are prioritized. Estimated or unavailable data is labeled in context.</p><a href="#" data-guide="life">Student life guide</a></div></div><div class="footer-bottom"><span>© 2026 University Tracker · Prototype data workspace</span><span>Data is for research planning; confirm final requirements with each institution.</span></div></div></footer>`; }

function homeView() { return `<section class="hero"><div class="container hero-grid"><div><div class="eyebrow">Global university & programme research</div><h1 class="display">Find the university that fits your <em>next chapter.</em></h1><p>Search official programme information, understand the fine print, and turn a shortlist into a plan you can act on.</p><form class="search-shell" data-search-form><input name="q" placeholder="Search universities, programmes, degrees, subjects…" value="${esc(state.query)}"/><button>Search the directory →</button></form><div class="quick-filters"><button class="filter-chip selected" data-quick-filter="Computer science">Computer science</button><button class="filter-chip" data-quick-filter="International scholarships">International scholarships</button><button class="filter-chip" data-quick-filter="Master's in Europe">Master’s in Europe</button><button class="filter-chip" data-quick-filter="Affordable options">Affordable options</button></div></div><div class="hero-art"><span class="art-number">01 / DISCOVER WITH CONTEXT</span><h2>Good decisions need more than a list.</h2><p>Compare the programme, the place, the requirements and the real cost—side by side.</p></div></div></section><div class="container"><div class="stats-strip"><div class="stat"><strong>12,480</strong><span>programmes indexed</span></div><div class="stat"><strong>68</strong><span>countries represented</span></div><div class="stat"><strong>1,940</strong><span>scholarship records</span></div><div class="stat"><strong>100%</strong><span>source status shown</span></div></div></div><section class="home-section"><div class="container"><div class="section-head"><div><div class="eyebrow">Start with the question</div><h2 class="section-title">Research with a little more <em>signal.</em></h2><p class="section-copy" style="margin-top:15px;">The directory is built for the questions that appear after the first search: what does it cost, what do I need, and where would I actually fit?</p></div><button class="text-link" data-view="discover">Explore the directory</button></div><div class="editorial-grid"><article class="editorial-card"><div class="editorial-image one"><span class="image-label">Programme fit</span></div><div class="editorial-body"><h3>See the detail behind the title</h3><p>Move from a broad subject to the campus, duration, mode, intake and curriculum that make a programme distinctive.</p><button class="text-link" data-view="discover">Find a programme</button></div></article><article class="editorial-card"><div class="editorial-image two"><span class="image-label">Admission context</span></div><div class="editorial-body"><h3>Read requirements in context</h3><p>Switch between domestic and international views, and select a qualification country when a university publishes it.</p><button class="text-link" data-guide="international">Understand the route</button></div></article><article class="editorial-card"><div class="editorial-image three"><span class="image-label">Planning tools</span></div><div class="editorial-body"><h3>Turn a shortlist into momentum</h3><p>Save programmes, compare trade-offs, track a deadline, and keep notes in one place.</p><button class="text-link" data-view="tracker">Open my tracker</button></div></article></div></div></section><section class="home-section alt"><div class="container guide-grid"><div><div class="eyebrow" style="color:var(--amber);">Plan beyond the offer</div><h2 class="section-title">The part after “find a course.”</h2><p class="section-copy" style="margin-top:20px;">Use lightweight guides for the application, the move and the life around the degree. Practical, clearly scoped and linked back to official sources.</p><div class="guide-list" style="margin-top:35px;"><button class="guide-row" data-guide="apply">How to apply without missing the small print</button><button class="guide-row" data-guide="international">International student essentials</button><button class="guide-row" data-guide="life">Student life, housing and support</button></div></div><div class="yellow-block"><h3>Compare what matters to you.</h3><p>No league tables. No made-up scores. Just transparent fields you can weigh for yourself.</p><button class="text-link" data-view="compare">Build a comparison</button></div></div></section>`; }

function filteredUniversities() { const q = state.query.trim().toLowerCase(); return universities.filter(u => { const hit = !q || [u.name,u.city,u.country,u.area,u.type].join(' ').toLowerCase().includes(q) || programs.some(p => p.universityId === u.id && [p.name,p.subject,p.level].join(' ').toLowerCase().includes(q)); const country = state.country === 'All countries' || u.country === state.country; return hit && country; }); }
function filterPanel() { return `<aside class="filter-panel ${state.filterOpen ? 'open' : ''}"><div style="display:flex;justify-content:space-between;align-items:center;"><h3>Filter research</h3><button class="clear-filters">Clear all</button></div><div class="filter-group"><label>Applicant type</label><div class="quick-filters" style="margin-top:0"><button class="filter-chip ${state.applicant === 'Domestic' ? 'selected' : ''}" data-applicant="Domestic">Domestic</button><button class="filter-chip ${state.applicant === 'International' ? 'selected' : ''}" data-applicant="International">International</button></div></div><div class="filter-group"><label>Qualification country</label><select data-filter="applicantCountry">${['India','United States','China','Nigeria','Brazil','Australia'].map(x=>`<option ${state.applicantCountry===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="filter-group"><label>Location</label><select data-filter="country"><option ${state.country==='All countries'?'selected':''}>All countries</option>${[...new Set(universities.map(u=>u.country))].map(x=>`<option ${state.country===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="filter-group"><label>Degree level</label><select data-filter="level"><option ${state.level==='All levels'?'selected':''}>All levels</option><option ${state.level==='Undergraduate'?'selected':''}>Undergraduate</option><option ${state.level==='Master’s'?'selected':''}>Master’s</option><option ${state.level==='PhD'?'selected':''}>PhD</option></select></div><div class="filter-group"><label>Study mode</label><select data-filter="mode"><option ${state.mode==='All modes'?'selected':''}>All modes</option><option ${state.mode==='On campus'?'selected':''}>On campus</option><option ${state.mode==='Online'?'selected':''}>Online</option><option ${state.mode==='Hybrid'?'selected':''}>Hybrid</option></select></div><div class="filter-group"><div class="toggle-line"><span>Scholarships available</span><button class="toggle ${state.scholarship ? 'on' : ''}" data-toggle="scholarship"><i></i></button></div></div><div class="filter-group"><p class="tiny muted">Filters are designed to compose. Results update without reloading the page.</p></div></aside>`; }
function universityCard(u) { const uniPrograms = programs.filter(p=>p.universityId===u.id); const hasScholar = u.id !== 'tum'; return `<article class="uni-card"><div class="uni-logo ${u.tone}">${u.initials}</div><div><div class="card-kicker">${u.country} · ${u.city}</div><h3>${u.name}</h3><p>${u.description}</p><div class="tag-row"><span class="tag blue">${u.type}</span><span class="tag">${u.programs} programmes</span><span class="tag">${uniPrograms.length} in sample</span>${hasScholar ? '<span class="tag green">Scholarships</span>' : ''}</div>${sourceNote(u.source, u.verified, u.sourceUrl)}</div><div class="card-actions">${saveButton('university', u.id, state.savedUniversities.includes(u.id))}<button class="arrow-button" data-university="${u.id}" aria-label="Open university">↗</button></div></article>`; }
function discoverView() { const results = filteredUniversities(); return `<section class="page-header"><div class="container page-header-row"><div><div class="eyebrow">Directory / evidence before opinion</div><h1>Find a better-fit <em>place to study.</em></h1><p>Search by university, programme, subject, country, degree or keyword. Every record keeps its source status visible.</p></div><button class="secondary-button" data-view="compare">Compare (${state.compareIds.length})</button></div></section><div class="context-bar"><div class="container context-inner"><span>Applicant view: <strong>${state.applicant}</strong> · Qualification country: <strong>${state.applicantCountry}</strong></span><button class="plain-button" data-guide="international">Why this matters</button></div></div><div class="container discovery-layout"><div><button class="mobile-filter-button" data-toggle-filters>${state.filterOpen ? 'Hide filters' : 'Show filters'} ↘</button>${filterPanel()}</div><section><div class="result-toolbar"><strong>${results.length} universities · ${state.query ? `matching “${esc(state.query)}”` : 'curated starting points'}</strong><select class="sort-select"><option>Most relevant</option><option>Recently verified</option><option>Programme count</option></select></div><input class="inline-search" data-discovery-search placeholder="Try “Computer Science”, “Canada” or “Sydney”…" value="${esc(state.query)}"/>${results.length ? `<div class="result-list">${results.map(universityCard).join('')}</div>` : `<div class="empty-compare"><h2>No exact match yet.</h2><p>Try a broader subject, country or university name.</p><button class="primary-button" data-clear-search>Clear search</button></div>`}</section></div>`; }

function universityView() { const u = getUni(state.selectedUniversity); const uniPrograms = programs.filter(p=>p.universityId===u.id); const tabs = ['Overview','Programs','Admissions','Tuition & costs','Scholarships','Resources']; return `<section class="profile-hero"><div class="container"><div class="breadcrumb"><button data-view="discover">Directory</button><span>/</span><span>${u.country}</span><span>/</span><span>${u.name}</span></div><div class="profile-top"><div class="uni-logo ${u.tone}">${u.initials}</div><div><div class="eyebrow">${u.type}</div><h1>${u.name}</h1><p>${u.description} Start with the official profile, then open a programme for requirement-level detail.</p><div class="tag-row"><span class="tag blue">${u.city}, ${u.country}</span><span class="tag">${u.programs} programmes</span><span class="tag green">Data verified ${u.verified}</span></div></div><div class="profile-actions">${saveButton('university', u.id, state.savedUniversities.includes(u.id))}<button class="secondary-button" data-view="compare">Compare saved</button></div></div><div class="tab-bar">${tabs.map(t=>`<button class="${state.universityTab===t?'active':''}" data-uni-tab="${t}">${t}</button>`).join('')}</div></div></section><section class="container profile-body"><div>${universityTabContent(u, uniPrograms)}</div><aside><div class="side-card"><h3>At a glance</h3><ul class="side-list"><li><span>Location</span><span>${u.city}</span></li><li><span>Institution type</span><span>${u.type.replace(' university','')}</span></li><li><span>Degrees</span><span>3 levels</span></li><li><span>Sample records</span><span>${uniPrograms.length}</span></li></ul></div><div class="side-card"><h3>Official links</h3><p>Use the university’s own admissions and programme pages for the final rule.</p><a class="text-link" style="display:inline-block;margin-top:16px;" href="${u.sourceUrl}" target="_blank" rel="noreferrer">Open source</a></div></aside></section>`; }
function universityTabContent(u, uniPrograms) { if (state.universityTab === 'Programs') return `<div class="programs-section" style="margin-top:0"><div class="eyebrow">Programme catalogue</div><h2>Find your route in.</h2><p class="lede">Browse the sample programme records below. In the production database, this surface is paginated and filterable by degree, department, campus, mode and intake.</p><div class="programs-toolbar"><strong>${uniPrograms.length} programme${uniPrograms.length===1?'':'s'} in this view</strong><select class="sort-select"><option>All degrees</option><option>Undergraduate</option><option>Master’s</option></select></div>${uniPrograms.map(programRow).join('')}</div>`; if (state.universityTab === 'Admissions') return `<div><div class="eyebrow">University-level context</div><h2>Admissions, with the caveat visible.</h2><p class="lede">University-level policies can set the route, but programme-specific requirements still win. Open a programme to see the relevant checklist.</p><div class="status-card" style="margin-top:28px"><h3>Applicant view: ${state.applicant}</h3><p>For ${state.applicantCountry}, country-specific equivalencies may apply. This sample surface never substitutes a generic rule for an official programme page.</p></div><div class="accordion" style="margin-top:26px"><div class="accordion-item"><button class="accordion-head" data-accordion="u-admit">Application routes and portals</button><div id="u-admit" class="accordion-content">Check whether the programme uses a national application service, the university’s portal, or a separate faculty route. The source link on each programme record is the starting point.</div></div><div class="accordion-item"><button class="accordion-head" data-accordion="u-intl">International qualification guidance</button><div id="u-intl" class="accordion-content">Equivalencies depend on your country, curriculum and year of completion. Select your qualification country and verify the current official page before applying.</div></div></div></div>`; if (state.universityTab === 'Tuition & costs') return `<div><div class="eyebrow">Planning estimate</div><h2>Budget the full year, not only tuition.</h2><p class="lede">Fees and living costs can vary by programme, residency, campus and year. This sample keeps official figures separate from planning estimates.</p><table class="cost-table"><thead><tr><th>Cost area</th><th>Status</th><th>Planning value</th></tr></thead><tbody><tr><td>Tuition</td><td><span class="tag green">Official where shown</span></td><td>Open programme record</td></tr><tr><td>Housing and food</td><td><span class="tag">Estimated</span></td><td>Model by city</td></tr><tr><td>Fees / insurance</td><td><span class="tag">Varies</span></td><td>Check current schedule</td></tr></tbody></table>${sourceNote('Source links attached per programme record', u.verified, u.sourceUrl)}</div>`; if (state.universityTab === 'Scholarships') return `<div><div class="eyebrow">Funding discovery</div><h2>Scholarships are a fit question.</h2><p class="lede">Browse provider, degree level, nationality, amount and deadline together. Eligibility is marked as published, not inferred.</p><button class="primary-button" data-view="scholarships" style="margin-top:25px">Explore scholarships →</button></div>`; if (state.universityTab === 'Resources') return `<div><div class="eyebrow">Source library</div><h2>Keep the official page close.</h2><p class="lede">Each record links out to the publisher responsible for the information. The directory is a research layer, not a replacement for the source.</p>${sourceNote(u.source, u.verified, u.sourceUrl)}<div class="rule" style="margin-top:30px;padding-top:22px"><a class="text-link" href="${u.sourceUrl}" target="_blank" rel="noreferrer">Open ${u.name} source</a></div></div>`; return `<div><div class="eyebrow">Overview</div><h2>Start with the shape of the place.</h2><p class="lede">${u.description} Explore the programme catalogue, then check admissions and cost information against the official pages that publish it.</p><div class="info-grid"><div class="info-cell"><small>Location</small><strong>${u.city}, ${u.country}</strong></div><div class="info-cell"><small>Academic areas</small><strong>${u.area}</strong></div><div class="info-cell"><small>Degree levels</small><strong>${u.degrees}</strong></div><div class="info-cell"><small>Programmes</small><strong>${u.programs} indexed</strong></div><div class="info-cell"><small>International view</small><strong>Country-aware</strong></div><div class="info-cell"><small>Scholarships</small><strong>${u.id === 'tum' ? 'Check provider' : 'Available in sample'}</strong></div></div>${sourceNote(u.source, u.verified, u.sourceUrl)}<div class="programs-section"><div class="programs-toolbar"><div><div class="eyebrow">In the directory</div><h2 style="margin-top:8px">Featured programmes</h2></div><button class="text-link" data-uni-tab="Programs">View all</button></div>${uniPrograms.map(programRow).join('')}</div></div>`; }
function programRow(p) { return `<article class="program-row"><div><div class="card-kicker">${p.level} · ${p.campus}</div><h3>${p.name}</h3><p>${p.degree} · ${p.duration} · ${p.mode}</p><div class="tag-row"><span class="tag blue">${p.subject}</span><span class="tag">${p.intake}</span><span class="tag green">${p.source.replace('Official ','')}</span></div></div><div class="program-meta"><strong>${p.tuition}</strong><br><span class="muted">tuition / year or see source</span></div><div class="program-meta">${saveButton('program', p.id, state.savedPrograms.includes(p.id))}</div><button class="arrow-button" data-program="${p.id}">↗</button></article>`; }

function programView() { const p = getProgram(state.selectedProgram); const u = getUni(p.universityId); const tabs = ['Overview','Admissions','Costs','Scholarships']; return `<section class="program-hero"><div class="container"><div class="breadcrumb"><button data-university="${u.id}">${u.name}</button><span>/</span><span>${p.name}</span></div><div class="eyebrow" style="color:var(--amber)">${p.degree} · ${p.level}</div><h1>${p.name}<br><em>${p.short}</em></h1><p>${p.overview}</p><div class="program-meta-grid"><div><small>University</small><strong>${u.name}</strong></div><div><small>Campus</small><strong>${p.campus}</strong></div><div><small>Duration</small><strong>${p.duration}</strong></div><div><small>Study mode</small><strong>${p.mode}</strong></div><div><small>Next intake</small><strong>${p.intake}</strong></div></div></div></section><section class="container program-body"><div><div class="program-tabs">${tabs.map(t=>`<button class="${state.programTab===t?'active':''}" data-program-tab="${t}">${t}</button>`).join('')}</div>${programTabContent(p, u)}</div><aside><div class="side-card"><h3>Research actions</h3>${saveButton('program', p.id, state.savedPrograms.includes(p.id))}<button class="secondary-button" style="width:100%;margin-top:12px" data-add-compare="${p.id}">${state.compareIds.includes(p.id) ? 'In comparison' : 'Add to compare'}</button><button class="primary-button" style="width:100%;margin-top:9px" data-track-program="${p.id}">${state.tracker.some(t=>t.programId===p.id) ? 'In my tracker' : 'Add to tracker'}</button></div><div class="side-card"><h3>Identifiers</h3><ul class="side-list"><li><span>University code</span><span>${p.code}</span></li><li><span>Government code</span><span>${p.governmentCode}</span></li><li><span>Classification</span><span>Not available</span></li></ul><p class="tiny muted" style="margin-top:13px">Identifiers are shown separately and never invented to fill a gap.</p></div>${sourceNote(p.source, p.verified, p.sourceUrl)}</aside></section>`; }
function programTabContent(p, u) { if (state.programTab === 'Admissions') return `<div class="section-block"><div class="eyebrow">Requirement matrix</div><h2>What you may need to show.</h2><p>Switch the applicant view to see how the checklist changes. For international applicants, qualification country is ${state.applicantCountry}.</p><div class="requirement-card" style="margin-top:25px"><div class="requirement-switch"><button class="${state.requirementMode==='Domestic'?'active':''}" data-requirement="Domestic">Domestic applicants</button><button class="${state.requirementMode==='International'?'active':''}" data-requirement="International">International applicants</button></div><div class="requirement-content"><ul class="check-list">${(state.requirementMode==='Domestic'?p.domestic:p.international).map(x=>`<li>${x}</li>`).join('')}</ul><div class="status-card"><h3>Applicant country: ${state.applicantCountry}</h3><p>Country-specific equivalencies and document rules are not implied here. Confirm them on the official admissions page for ${p.name}.</p></div></div></div>${sourceNote('Official admissions source', p.verified, p.sourceUrl)}</div>`; if (state.programTab === 'Costs') return `<div class="section-block"><div class="eyebrow">Costs & transparency</div><h2>Know what is official—and what is a plan.</h2><p>Tuition below is either a published figure from the source or explicitly marked for follow-up. Living cost is always a planning estimate until a city-specific budget is built.</p><div class="cost-estimate" style="margin-top:28px">${p.tuition}</div><div class="tiny muted" style="margin-top:5px">International tuition signal · confirm period and cohort on source</div><table class="cost-table"><thead><tr><th>Cost component</th><th>Data status</th><th>Value</th></tr></thead><tbody><tr><td>Tuition</td><td><span class="tag green">Published / see source</span></td><td>${p.tuition}</td></tr><tr><td>Housing + meal plan</td><td><span class="tag">Planning estimate</span></td><td>${p.living}</td></tr><tr><td>Health / student fees</td><td><span class="tag">Varies</span></td><td>See fee schedule</td></tr></tbody></table>${sourceNote('Official programme / fee source', p.verified, p.sourceUrl)}</div>`; if (state.programTab === 'Scholarships') return `<div class="section-block"><div class="eyebrow">Funding match</div><h2>Scholarships linked to the decision.</h2><p>Check eligibility criteria, award terms and current deadlines on the provider page. This programme appears in the funding discovery set.</p><div class="scholarship-card" style="margin-top:25px;max-width:680px"><div class="card-kicker">${u.name} · international applicants</div><h3>${u.id==='uoft' ? 'Lester B. Pearson International Scholarship' : 'Find awards for this programme'}</h3><p>${u.id==='uoft' ? 'A university scholarship record is attached to this profile. Eligibility is published through the official provider and may require nomination.' : 'Use the scholarship directory to filter by provider, degree level, nationality and published eligibility.'}</p><div class="scholarship-bottom"><span class="amount">${u.id==='uoft' ? 'Full support' : 'Browse awards'}</span><button class="text-link" data-view="scholarships">Open scholarship view</button></div></div></div>`; return `<div class="section-block"><div class="eyebrow">Programme detail</div><h2>Built for the questions after the click.</h2><p>${p.overview}</p><div class="info-grid"><div class="info-cell"><small>Faculty / area</small><strong>${p.area}</strong></div><div class="info-cell"><small>Subject</small><strong>${p.subject}</strong></div><div class="info-cell"><small>Intake</small><strong>${p.intake}</strong></div><div class="info-cell"><small>Co-op / industry</small><strong>${p.coOp}</strong></div><div class="info-cell"><small>Research / thesis</small><strong>${p.thesis}</strong></div><div class="info-cell"><small>Language</small><strong>${p.language}</strong></div></div></div><div class="section-block"><div class="eyebrow">Curriculum snapshot</div><h2>Expand the structure.</h2><div class="accordion"><div class="accordion-item"><button class="accordion-head" data-accordion="curriculum">Core curriculum and required courses</button><div id="curriculum" class="accordion-content">The programme’s official curriculum should be treated as the canonical course list. This prototype keeps a progressive-disclosure slot for core modules, electives, concentrations and credit rules.</div></div><div class="accordion-item"><button class="accordion-head" data-accordion="experience">Practical experience and research</button><div id="experience" class="accordion-content">${p.coOp}. ${p.thesis}. Availability and conditions vary by stream, year and capacity; verify with the programme source.</div></div><div class="accordion-item"><button class="accordion-head" data-accordion="identifiers">Programme identifiers and classifications</button><div id="identifiers" class="accordion-content">University programme code: ${p.code}. Government programme code: ${p.governmentCode}. Classification systems are jurisdiction-specific and shown as unavailable when a source does not publish one.</div></div></div></div>`; }

function guideView() { const g = getGuide(); return `<section class="guide-hero"><div class="container"><div class="eyebrow">Student planning guide</div><h1>${g.title}</h1><p>${g.intro}</p></div></section><section class="container guide-body"><nav class="guide-nav"><button class="${state.guide==='apply'?'active':''}" data-guide="apply">How to apply</button><button class="${state.guide==='international'?'active':''}" data-guide="international">International students</button><button class="${state.guide==='life'?'active':''}" data-guide="life">Student life</button></nav><div><div class="step-grid">${g.steps.map(s=>`<article class="step-card"><div class="step-number">${s[0]}</div><h3>${s[1]}</h3><p>${s[2]}</p></article>`).join('')}</div><div class="callout"><strong>Keep the source in the loop.</strong><p>${g.callout}</p></div></div></section>`; }
function scholarshipsView() { return `<section class="page-header"><div class="container page-header-row"><div><div class="eyebrow">Funding / published eligibility</div><h1>Scholarships without the <em>fog.</em></h1><p>Explore awards by provider, student type, degree level and published eligibility. The checklist shows what is known—not what we guessed.</p></div><button class="secondary-button" data-view="tracker">View my tracker</button></div></section><div class="context-bar"><div class="container context-inner"><span>Showing awards relevant to <strong>${state.applicant}</strong> applicants from <strong>${state.applicantCountry}</strong></span><button class="plain-button" data-guide="international">International funding guide</button></div></div><div class="container scholarship-grid">${scholarships.map(scholarshipCard).join('')}</div>`; }
function scholarshipCard(s) { const saved = state.savedScholarships.includes(s.id); return `<article class="scholarship-card"><div class="card-kicker">${s.provider} · ${s.type}</div><h3>${s.name}</h3><p>${s.note}</p><div class="eligibility">${s.eligible.map(x=>`<span>✓ ${x}</span>`).join('')}${s.notEligible.map(x=>`<span class="no">— ${x}</span>`).join('')}</div><div class="scholarship-bottom"><div><div class="amount">${s.amount}</div><div class="tiny muted" style="margin-top:5px">Deadline: ${s.deadline}</div></div><div style="text-align:right">${saveButton('scholarship', s.id, saved)}<br><a class="text-link" href="${s.url}" target="_blank" rel="noreferrer">Official source</a></div></div></article>`; }
function compareView() { const items = state.compareIds.map(getProgram).filter(Boolean); return `<section class="page-header"><div class="container page-header-row"><div><div class="eyebrow">Side-by-side research</div><h1>Compare the trade-offs, <em>not the hype.</em></h1><p>Keep the fields readable on desktop and scrollable on mobile. Add programmes from any programme page or directory card.</p></div><button class="secondary-button" data-view="discover">Add a programme</button></div></section><div class="container compare-wrap">${items.length ? `<table class="compare-table"><thead><tr><th>Field</th>${items.map(p=>`<th><strong>${p.name}</strong><span>${getUni(p.universityId).name}</span><br><button class="plain-button" style="margin-top:11px;color:#fff;border-color:rgba(255,255,255,.5)" data-remove-compare="${p.id}">Remove</button></th>`).join('')}</tr></thead><tbody>${compareRow('Country / city',items,p=>`${getUni(p.universityId).country} · ${getUni(p.universityId).city}`)}${compareRow('Degree / level',items,p=>`${p.degree} · ${p.level}`)}${compareRow('Duration / mode',items,p=>`${p.duration} · ${p.mode}`)}${compareRow('Tuition signal',items,p=>p.tuition)}${compareRow('International requirements',items,p=>p.international[0])}${compareRow('Language',items,p=>p.language)}${compareRow('Next intake / deadline',items,p=>`${p.intake} · ${p.deadline}`)}${compareRow('Co-op / research',items,p=>`${p.coOp} · ${p.thesis}`)}${compareRow('Identifiers',items,p=>`${p.code} · ${p.governmentCode}`)}</tbody></table>` : `<div class="empty-compare"><h2>Your comparison is waiting.</h2><p>Add two or more programmes to see the fields together.</p><button class="primary-button" data-view="discover">Explore programmes</button></div>`}</div>`; }
function compareRow(label, items, value) { return `<tr><th>${label}</th>${items.map(p=>`<td>${value(p)}</td>`).join('')}</tr>`; }
function trackerView() { return `<section class="page-header"><div class="container page-header-row"><div><div class="eyebrow">Your research desk</div><h1>Make the next step <em>visible.</em></h1><p>Saved programmes, deadlines and notes in one lightweight workspace. No prediction—just momentum.</p></div><button class="primary-button" data-view="discover">Add a programme</button></div></section><div class="container tracker-grid"><section><div class="result-toolbar"><strong>${state.tracker.length} tracked programme${state.tracker.length===1?'':'s'}</strong><span class="muted tiny">Last updated just now</span></div>${state.tracker.map(trackerItem).join('')}</section><aside><div class="progress-card"><h3>Application rhythm</h3><p>Keep your shortlist moving by giving every programme a current stage.</p><div class="progress-bar"><span style="width:${Math.max(12, Math.round(state.tracker.filter(t=>t.stage!=='Researching').length / Math.max(state.tracker.length,1)*100))}%"></span></div><div class="progress-label"><span>In motion</span><strong>${state.tracker.filter(t=>t.stage!=='Researching').length}/${state.tracker.length}</strong></div></div><div class="checklist-card"><h3>Personal checklist</h3><label><input type="checkbox"> Passport / identity document</label><label><input type="checkbox"> Academic transcripts</label><label><input type="checkbox"> Language result</label><label><input type="checkbox"> Funding plan</label><label><input type="checkbox"> Reference / statement</label></div></aside></div>`; }
function trackerItem(item) { const p = getProgram(item.programId); const u = getUni(p.universityId); return `<article class="tracker-item"><div><div class="card-kicker">${u.name} · ${p.degree}</div><h3>${p.name}</h3><p>${item.note}</p><small>Deadline signal: ${item.deadline}</small></div><select class="stage-select" data-stage="${p.id}">${['Researching','Shortlisted','Preparing application','Application started','Application submitted','Interview','Decision pending','Accepted','Rejected','Waitlisted'].map(x=>`<option ${x===item.stage?'selected':''}>${x}</option>`).join('')}</select></article>`; }

function render() { let content = state.view === 'home' ? homeView() : state.view === 'discover' ? discoverView() : state.view === 'university' ? universityView() : state.view === 'program' ? programView() : state.view === 'guide' ? guideView() : state.view === 'scholarships' ? scholarshipsView() : state.view === 'compare' ? compareView() : trackerView(); document.querySelector('#app').innerHTML = shell(content); bind(); }
function bind() {
  document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click', e=>{ e.preventDefault(); navigate(el.dataset.view); }));
  document.querySelectorAll('[data-guide]').forEach(el=>el.addEventListener('click', e=>{ e.preventDefault(); navigate('guide', {guide: el.dataset.guide}); }));
  document.querySelectorAll('[data-university]').forEach(el=>el.addEventListener('click', ()=>navigate('university',{selectedUniversity:el.dataset.university, universityTab:'Overview'})));
  document.querySelectorAll('[data-program]').forEach(el=>el.addEventListener('click', ()=>navigate('program',{selectedProgram:el.dataset.program, programTab:'Overview'})));
  document.querySelectorAll('[data-search-form]').forEach(form=>form.addEventListener('submit', e=>{e.preventDefault(); state.query = new FormData(form).get('q') || ''; navigate('discover');}));
  document.querySelectorAll('[data-quick-filter]').forEach(el=>el.addEventListener('click', ()=>{state.query=el.dataset.quickFilter; navigate('discover');}));
  document.querySelectorAll('[data-discovery-search]').forEach(el=>el.addEventListener('input', ()=>{state.query=el.value; clearTimeout(window.__search); window.__search=setTimeout(render,180);}));
  document.querySelectorAll('[data-clear-search]').forEach(el=>el.addEventListener('click', ()=>{state.query='';render();}));
  document.querySelectorAll('[data-filter]').forEach(el=>el.addEventListener('change', ()=>{state[el.dataset.filter]=el.value;render();}));
  document.querySelectorAll('[data-applicant]').forEach(el=>el.addEventListener('click', ()=>{state.applicant=el.dataset.applicant; state.requirementMode=el.dataset.applicant; render();}));
  document.querySelectorAll('[data-toggle]').forEach(el=>el.addEventListener('click', ()=>{state[el.dataset.toggle]=!state[el.dataset.toggle];render();}));
  document.querySelectorAll('[data-toggle-filters]').forEach(el=>el.addEventListener('click', ()=>{state.filterOpen=!state.filterOpen;render();}));
  document.querySelectorAll('.clear-filters').forEach(el=>el.addEventListener('click', ()=>{Object.assign(state,{country:'All countries',level:'All levels',mode:'All modes',scholarship:false,query:''});render();}));
  document.querySelectorAll('[data-save-type]').forEach(el=>el.addEventListener('click', ()=>{const key=el.dataset.saveType==='university'?'savedUniversities':el.dataset.saveType==='program'?'savedPrograms':'savedScholarships'; const index=state[key].indexOf(el.dataset.id); if(index>=0) state[key].splice(index,1); else state[key].push(el.dataset.id); showToast(index>=0?'Removed from saved items':'Saved to your research list'); render();}));
  document.querySelectorAll('[data-uni-tab]').forEach(el=>el.addEventListener('click', ()=>{state.universityTab=el.dataset.uniTab;render();}));
  document.querySelectorAll('[data-program-tab]').forEach(el=>el.addEventListener('click', ()=>{state.programTab=el.dataset.programTab;render();}));
  document.querySelectorAll('[data-requirement]').forEach(el=>el.addEventListener('click', ()=>{state.requirementMode=el.dataset.requirement;render();}));
  document.querySelectorAll('[data-add-compare]').forEach(el=>el.addEventListener('click', ()=>{if(!state.compareIds.includes(el.dataset.addCompare)) { if(state.compareIds.length>=4) return showToast('Compare up to four programmes at once'); state.compareIds.push(el.dataset.addCompare); showToast('Added to comparison'); } else showToast('Already in comparison'); render();}));
  document.querySelectorAll('[data-remove-compare]').forEach(el=>el.addEventListener('click', ()=>{state.compareIds=state.compareIds.filter(id=>id!==el.dataset.removeCompare);render();}));
  document.querySelectorAll('[data-track-program]').forEach(el=>el.addEventListener('click', ()=>{if(!state.tracker.some(t=>t.programId===el.dataset.trackProgram)) {const p=getProgram(el.dataset.trackProgram);state.tracker.push({programId:p.id,stage:'Researching',deadline:p.deadline,note:'Add your next action'});showToast('Added to application tracker');} else showToast('Already in your tracker');render();}));
  document.querySelectorAll('[data-stage]').forEach(el=>el.addEventListener('change', ()=>{const item=state.tracker.find(t=>t.programId===el.dataset.stage); if(item){item.stage=el.value;showToast('Tracker stage updated');render();}}));
  document.querySelectorAll('[data-accordion]').forEach(el=>el.addEventListener('click', ()=>{el.classList.toggle('open');document.getElementById(el.dataset.accordion)?.classList.toggle('show');}));
}

render();
